const asObj = (v) => (v && typeof v === 'object' && !Array.isArray(v) ? v : {});
const clamp = (v, n) => String(v || '').trim().slice(0, n);
const truthy = (v) => v === true || ['true','1','yes','ok'].includes(String(v || '').trim().toLowerCase());
let body = asObj($json.body);
if (!Object.keys(body).length && typeof $json.body === 'string') {
  try { body = asObj(JSON.parse($json.body)); } catch {}
}
if (!Object.keys(body).length) body = asObj($json);
const jobId = clamp(body.job_id || body.jobId, 160);
const status = clamp(body.status, 40);
if (!jobId || !status) {
  return [{ json: { route: 'error', statusCode: 400, error_code: 'JOB_ID_STATUS_REQUIRED', message: 'job_id and status are required' } }];
}
const normalizedStatus = status.toLowerCase();
const requestId = clamp(body.request_id || body.correlation_id || body.correlationId || body.idempotency_key, 180);
const completionProof = clamp(body.completion_proof || body.completionProof || body.proof || body.evidence, 600);
const completionAck = truthy(body.completion_ack || body.completionAck || (normalizedStatus === 'done' || normalizedStatus === 'completed' || normalizedStatus === 'success'));
if ((normalizedStatus === 'done' || normalizedStatus === 'completed' || normalizedStatus === 'success') && (!completionAck || !completionProof || !requestId)) {
  return [{ json: { route: 'error', statusCode: 422, error_code: 'DONE_REQUIRES_PROOF', message: 'done requires completion_ack, completion_proof and request_id' } }];
}
const base = String($env.GOV_CLIENT_GOVHUB_BASE_URL || 'https://govhub.proforma.net.br').replace(/\/+$/,'');
const partnerId = String($env.GOV_CLIENT_PARTNER_ID || 'proforma-partner-test-001').trim();
const statusBody = {
  job_id: jobId,
  status,
  message: clamp(body.message, 280),
  source: 'medcore-n8n',
  ...(requestId ? { request_id: requestId, correlation_id: requestId } : {}),
  ...(completionAck ? { completion_ack: true } : {}),
  ...(completionProof ? { completion_proof: completionProof } : {})
};
return [{ json: { route: 'valid', govhub_status_url: `${base}/webhook/govhub-status`, partner_id: partnerId, status_body: statusBody } }];

const statusCode = Number($json.statusCode || 0);
const body = ($json.body && typeof $json.body === 'object') ? $json.body : {};
const ok = !$json.error && statusCode >= 200 && statusCode < 300 && body.ack === true;
if (ok) {
  return [{ json: { relay_ok: true, status_code: statusCode, body } }];
}
return [{ json: { relay_ok: false, statusCode: statusCode || 502, error_code: String(body.error_code || ($json.error ? 'RELAY_HTTP_ERROR' : 'RELAY_REJECTED')), message: String(body.message || $json?.error?.message || 'relay failed').slice(0, 250) } }];
